create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(username=lower(username) and username ~ '^[a-z0-9_.]{3,24}$'),display_name text not null default '',bio text not null default '',avatar_url text,cover_url text,is_private boolean not null default false,is_verified boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.blocks(blocker_id uuid not null references public.profiles(id) on delete cascade,blocked_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table if not exists public.follows(follower_id uuid not null references public.profiles(id) on delete cascade,following_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'pending' check(status in('pending','accepted')),created_at timestamptz default now(),primary key(follower_id,following_id),check(follower_id<>following_id));
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,content text,media_url text,media_type text check(media_type is null or media_type in('image','video')),visibility text not null default 'public' check(visibility in('public','private')),created_at timestamptz not null default now(),check(coalesce(length(content),0)>0 or media_url is not null));
create table if not exists public.likes(post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz default now(),primary key(post_id,user_id));
create table if not exists public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,body text not null check(length(body) between 1 and 2000),created_at timestamptz default now());
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),created_at timestamptz default now());
create table if not exists public.conversation_members(conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,primary key(conversation_id,user_id));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,body text not null check(length(body) between 1 and 5000),read_at timestamptz,created_at timestamptz default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references public.profiles(id) on delete cascade,actor_id uuid references public.profiles(id) on delete set null,kind text not null,entity_id uuid,read_at timestamptz,created_at timestamptz default now());
create table if not exists public.verification_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,note text not null check(length(note) between 20 and 1500),status text not null default 'pending' check(status in('pending','approved','rejected')),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,created_at timestamptz default now());
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path='' as $$ declare u text; begin u:=lower(coalesce(new.raw_user_meta_data->>'username','user_'||substr(new.id::text,1,8))); if u !~ '^[a-z0-9_.]{3,24}$' then u:='user_'||substr(new.id::text,1,8); end if; insert into public.profiles(id,username,display_name) values(new.id,u,coalesce(new.raw_user_meta_data->>'display_name','')) on conflict(id) do nothing; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.new_profile();
create or replace function public.find_profile_exact(search_username text) returns table(id uuid,username text,display_name text,avatar_url text,is_verified boolean,is_private boolean) language sql stable security definer set search_path=public as $$ select p.id,p.username,p.display_name,p.avatar_url,p.is_verified,p.is_private from public.profiles p where auth.uid() is not null and p.username=lower(trim(both '@' from search_username)) and p.id<>auth.uid() and not exists(select 1 from public.blocks b where (b.blocker_id=auth.uid() and b.blocked_id=p.id) or (b.blocker_id=p.id and b.blocked_id=auth.uid())) limit 1 $$;
grant execute on function public.find_profile_exact(text) to authenticated;
create or replace function public.follow_profile(target_id uuid) returns text language plpgsql security definer set search_path=public as $$ declare priv boolean; begin if auth.uid() is null or auth.uid()=target_id then raise exception 'Not allowed'; end if; if exists(select 1 from public.blocks where (blocker_id=auth.uid() and blocked_id=target_id) or (blocker_id=target_id and blocked_id=auth.uid())) then raise exception 'Account unavailable'; end if; select is_private into priv from public.profiles where id=target_id; if priv is null then raise exception 'Account not found'; end if; insert into public.follows(follower_id,following_id,status) values(auth.uid(),target_id,case when priv then 'pending' else 'accepted' end) on conflict do nothing; return case when priv then 'pending' else 'accepted' end; end $$;
grant execute on function public.follow_profile(uuid) to authenticated;
create or replace function public.review_verification(request_id uuid,decision text) returns void language plpgsql security definer set search_path=public as $$ declare admin_ok boolean; target uuid; begin select exists(select 1 from public.profiles where id=auth.uid() and username='teamwayss') into admin_ok; if not admin_ok or decision not in('approved','rejected') then raise exception 'Only @teamwayss can review requests'; end if; update public.verification_requests set status=decision,reviewed_by=auth.uid(),reviewed_at=now() where id=request_id and status='pending' returning user_id into target; if target is null then raise exception 'Pending request not found'; end if; update public.profiles set is_verified=(decision='approved') where id=target; end $$;
grant execute on function public.review_verification(uuid,text) to authenticated;
alter table public.profiles enable row level security; alter table public.blocks enable row level security; alter table public.follows enable row level security; alter table public.posts enable row level security; alter table public.likes enable row level security; alter table public.comments enable row level security; alter table public.conversation_members enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security; alter table public.notifications enable row level security; alter table public.verification_requests enable row level security;
create policy "profile lookup" on public.profiles for select to authenticated using(id=auth.uid() or (not is_private and not exists(select 1 from public.blocks b where (b.blocker_id=auth.uid() and b.blocked_id=id) or (b.blocker_id=id and b.blocked_id=auth.uid()))));
revoke update on public.profiles from authenticated;
grant update(display_name,bio,avatar_url,cover_url,is_private) on public.profiles to authenticated;
create policy "edit own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "own blocks read" on public.blocks for select to authenticated using(blocker_id=auth.uid());
create policy "own blocks add" on public.blocks for insert to authenticated with check(blocker_id=auth.uid());
create policy "own blocks delete" on public.blocks for delete to authenticated using(blocker_id=auth.uid());
create policy "follow participants read" on public.follows for select to authenticated using(follower_id=auth.uid() or following_id=auth.uid());
create policy "follow own" on public.follows for insert to authenticated with check(follower_id=auth.uid());
create policy "follow accept" on public.follows for update to authenticated using(following_id=auth.uid()) with check(following_id=auth.uid());
create policy "follow delete" on public.follows for delete to authenticated using(follower_id=auth.uid() or following_id=auth.uid());
create policy "visible posts" on public.posts for select to authenticated using((user_id=auth.uid() or (visibility='public' and exists(select 1 from public.profiles p where p.id=user_id and not p.is_private))) and not exists(select 1 from public.blocks b where (b.blocker_id=auth.uid() and b.blocked_id=user_id) or (b.blocker_id=user_id and b.blocked_id=auth.uid())));
create policy "own posts insert" on public.posts for insert to authenticated with check(user_id=auth.uid());
create policy "own posts update" on public.posts for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own posts delete" on public.posts for delete to authenticated using(user_id=auth.uid());
create policy "likes visible" on public.likes for select to authenticated using(exists(select 1 from public.posts p where p.id=post_id));
create policy "like own" on public.likes for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.posts p where p.id=post_id));
create policy "unlike own" on public.likes for delete to authenticated using(user_id=auth.uid());
create policy "comments visible" on public.comments for select to authenticated using(exists(select 1 from public.posts p where p.id=post_id));
create policy "comment own" on public.comments for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.posts p where p.id=post_id));
create or replace function public.is_conversation_member(cid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.conversation_members where conversation_id=cid and user_id=auth.uid()) $$;
grant execute on function public.is_conversation_member(uuid) to authenticated;
create policy "member conversation read" on public.conversations for select to authenticated using(public.is_conversation_member(id));
create policy "member list read" on public.conversation_members for select to authenticated using(public.is_conversation_member(conversation_id));
create policy "member add self" on public.conversation_members for insert to authenticated with check(user_id=auth.uid());
create policy "member messages read" on public.messages for select to authenticated using(public.is_conversation_member(conversation_id));
create policy "member messages send" on public.messages for insert to authenticated with check(sender_id=auth.uid() and public.is_conversation_member(conversation_id));
create policy "notification owner read" on public.notifications for select to authenticated using(recipient_id=auth.uid());
create policy "notification owner update" on public.notifications for update to authenticated using(recipient_id=auth.uid()) with check(recipient_id=auth.uid());
create policy "verification owner read" on public.verification_requests for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.username='teamwayss'));
create policy "verification own request" on public.verification_requests for insert to authenticated with check(user_id=auth.uid());
alter publication supabase_realtime add table public.messages; alter publication supabase_realtime add table public.notifications;
